"""Read-only R7 audit: synthetic control flow, not a source/model acceptance."""
from pathlib import Path
from types import SimpleNamespace
import hashlib
import json
import sys

ROOT=Path('C:/Users/郑曾波/Projects/company-wiki')
TMP=Path(__file__).parent
sys.path[:0]=[str(ROOT),str(ROOT/'src')]
from tools import pre_push_gate as gate
from tools.holdout_replay import producer
from tools.document_understanding_benchmark import phase_c_observer as observer
from tools.source_root_portability import report

out=[]
messages=[]
gate._print_output=lambda text:messages.append({'characters':len(text),'sha256':hashlib.sha256(text.encode('utf-8')).hexdigest()})
for name,stream,size,expected in [('quiet','stdout',0,0),('stdout_cap','stdout',gate.STDOUT_CAP_BYTES+1,125),('stderr_cap','stderr',gate.STDERR_CAP_BYTES+1,125)]:
    code='import sys;sys.'+stream+'.buffer.write(b"x"*'+str(size)+');sys.'+stream+'.flush()'
    value=gate._run([sys.executable,'-B','-c',code],'synthetic-'+name,timeout=10)
    assert value==expected,(name,value)
    out.append({'probe':name,'returncode':value,'configured_stdout_cap':gate.STDOUT_CAP_BYTES,'configured_stderr_cap':gate.STDERR_CAP_BYTES,'child_requested_bytes':size})

fake=TMP/'producer';(fake/'.git').mkdir(parents=True);(fake/'tools').mkdir()
real_git=producer._git;calls=[]
def fake_git(root,*args):
    calls.append(args)
    return '1'*40 if args==('rev-parse','HEAD') else '?? tools/unrelated_notes.py' if args[:2]==('status','--porcelain') else 'synthetic'
producer._git=fake_git
try:
    try:producer.verify_producer(fake,'1'*40)
    except producer.ProducerError as exc:out.append({'probe':'unrelated_untracked_tool_refuses_holdout','exception':type(exc).__name__,'reason':str(exc),'git_calls':calls})
    else:raise AssertionError('Expected current broad clean-tree refusal')
finally:producer._git=real_git

state={'prepared':False}
def fake_prepare(store,draft,payload):state['prepared']=True;return object()
try:observer.prepared_artifact_observer(fake_prepare,{})(None,None,b'x'*(observer.PREPARED_PAYLOAD_MAX_BYTES+1))
except ValueError as exc:out.append({'probe':'observer_size_failure_after_successful_owner_prepare','exception':type(exc).__name__,'reason':str(exc),'owner_prepare_returned_successfully':state['prepared'],'prepared_limit_bytes':observer.PREPARED_PAYLOAD_MAX_BYTES})
else:raise AssertionError('Expected observer-only size exception')
assert state['prepared']

attempt=TMP/'report';attempt.mkdir()
try:report.write_report(SimpleNamespace(path=attempt),{'synthetic_trace':'x'*(report.MAX_REPORT_BYTES+1)})
except RuntimeError as exc:out.append({'probe':'oversize_final_report_not_written','exception':type(exc).__name__,'reason':str(exc),'file_exists':(attempt/'report.json').exists(),'report_limit_bytes':report.MAX_REPORT_BYTES})
else:raise AssertionError('Expected current report-only size refusal')

(TMP/'results.json').write_text(json.dumps({'probes':out,'gate_message_metadata':messages,'real_source_access':False,'model_calls':0,'external_network':False},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(json.dumps({'probes':len(out),'returncodes':[r['returncode'] for r in out if 'returncode' in r],'post_prepare_observer_failure':state['prepared'],'all_expected_current_behaviors_observed':True}))
